 * <p>
 * User names are managed in a case-sensitive manner, however user lookups occur in a
 * case-insensitive manner.  Duplicate names with different case are not supported. 
 */
public class UserManager {

	static readonly Logger log = LogManager.getLogger(typeof(UserManager));

	public static readonly string X500_NAME_FORMAT = X500Principal.RFC2253;

	public static readonly string ANONYMOUS_USERNAME = User.ANONYMOUS_USERNAME;

	public static readonly string USER_PASSWORD_FILE = "users";
	public static readonly string DN_LOG_FILE = "UnknownDN.log";

	private static readonly string SSH_KEY_FOLDER = LocalFileSystem.HIDDEN_DIR_PREFIX + "ssh";
	private static readonly string SSH_PUBKEY_EXT = ".pub";

	private static readonly char[] DEFAULT_PASSWORD = "changeme".toCharArray();

	private static readonly int DEFAULT_PASSWORD_TIMEOUT_DAYS = 1; // 24-hours
	private static readonly int NO_EXPIRATION = -1;

