	/**
	 * Construct server user manager
	 * @param repositoryMgr repository manager
	 * @param enableLocalPasswords if true user passwords will be maintained 
	 * 			within local 'users' file
	 * @param defaultPasswordExpirationDays password expiration in days when 
	 * 			local passwords are enabled (0 = no expiration)
	 */
	UserManager(RepositoryManager repositoryMgr, bool enableLocalPasswords,
			int defaultPasswordExpirationDays) {
		this.repositoryMgr = repositoryMgr;
		this.enableLocalPasswords = enableLocalPasswords;
		if (defaultPasswordExpirationDays < 0) {
			defaultPasswordExpirationDays = DEFAULT_PASSWORD_TIMEOUT_DAYS;
		}
		this.defaultPasswordExpirationMS = defaultPasswordExpirationDays * 24L * 3600L * 1000L;
		log.info("Instantiating User Manager " +
			(enableLocalPasswords ? "(w/password management)" : ""));

		userFile = new File(repositoryMgr.getRootDir(), USER_PASSWORD_FILE);
		try {
			readUserListIfNeeded();
			clearExpiredPasswords();
			int size = userMap.size();
			log.info("User file contains " + size + (size == 1 ? " entry" : " entries"));
		}
		catch (FileNotFoundException e) {
			log.error("Existing User file not found.");
		}
		catch (IOException e) {
			log.error(e);
		}

		log.info("Known Users:");
		Iterator<string> iter = userMap.keySet().iterator();
		while (iter.hasNext()) {
			string name = iter.next();
			string dnStr = "";
			UserEntry entry = userMap.get(name);
			if (entry != null) {
				X500Principal x500User = entry.x500Name;
				if (x500User != null) {
					dnStr = " DN={" + x500User.getName() + "}";
				}
			}
			log.info("   " + name + dnStr);
		}

		sshDir = new File(repositoryMgr.getRootDir(), SSH_KEY_FOLDER);
		initSSH();
	}

	private void initSSH() {

		if (!sshDir.exists()) {
			sshDir.mkdir();
			return;
		}

		string[] list = sshDir.list((dir, name) => name.endsWith(SSH_PUBKEY_EXT));
		if (list.length == 0) {
			return;
		}

		log.info("Users with stored SSH public key:");
		foreach (string fname in list) {
			string user = fname.substring(0, fname.length() - SSH_PUBKEY_EXT.length());
			if (!userMap.containsKey(user)) {
				continue; // ignore invalid user
			}
			log.info("   " + user);
		}
	}

	/**
	 * Get the SSH public key file for the specified user if it exists.
	 * @param username user name/SID
	 * @return SSH public key file or null if key unavailable
	 */
	public File getSSHPubKeyFile(string username) {
		if (username == null) {
			return null;
		}
		username = username.toLowerCase();
		if (!userMap.containsKey(username)) {
			return null;
		}

		List<File> sshFiles = findFilesCaseInsensitive(sshDir, username + SSH_PUBKEY_EXT);
		if (sshFiles.isEmpty()) {
			return null;
		}

		if (sshFiles.size() != 1) {
			log.error(sshDir + " contains multiple SSH public key files for: " + username);
			return null;
		}

		return sshFiles.get(0);
	}

	public static List<File> findFilesCaseInsensitive(File directory, string targetLowerCase) {
		List<File> result = new();

		if (directory == null || !directory.isDirectory()) {
			return result;
		}

		File[] files = directory.listFiles();
		if (files == null) {
			return result;
		}

		foreach (File file in files) {
			// Only match files, skip directories
			if (file.isFile() && file.getName().toLowerCase().equals(targetLowerCase)) {
				result.add(file);
			}
		}

		return result;
	}

	/**
	 * Add a user.
	 * @param username user name/SID
	 * @param passwordHash MD5 hash of initial password or null if explicit password reset required
	 * @param x500User X500 user name (may be null)
	 * @throws DuplicateNameException if username already exists
	 * @throws IOException if IO error occurs
	 */
	private void addUser(string username, char[] passwordHash, X500Principal x500User)
    {
		if (username == null) {
			throw new IllegalArgumentException();
		}
		lock (repositoryMgr) {
			if (userMap.containsKey(username)) {
				throw new DuplicateNameException("User " + username + " already exists");
			}
			UserEntry entry =
				new UserEntry(username, x500User, passwordHash, (new Date()).getTime());
			userMap.put(username, entry);
			if (x500User != null) {
				dnLookupMap.put(x500User, entry);
			}
			writeUserList();
			log.info("User '" + username + "' added");
		}
	}

