	private static bool readUserList(File file, UserMap<UserEntry> usersIndexByName,
			Map<X500Principal, UserEntry> x500LookupMap)
    {
		bool userMapMutated = false;
		using (BufferedReader br = new BufferedReader(new FileReader(file)))
{
			string line;
			while ((line = br.readLine()) != null) {
				if (line.startsWith("#")) {
					continue;
				}

				X500Principal x500Name = null;
				char[] passwordHash = null;
				long passwordTime = 0;

				StringTokenizer st = new StringTokenizer(line, ":");
				string username = st.nextToken();
				if (!isValidUserName(username)) {
					log.error("Invalid user name, skipping: " + username);
					userMapMutated = true;
					continue;
				}

				if (usersIndexByName.containsKey(username)) {
					log.error("Duplicate (case-insenstive) user name discarded: " + username);
					userMapMutated = true;
					continue;
				}

				// Password Hash
				if (st.hasMoreTokens()) {
					passwordHash = st.nextToken().toCharArray();

					// Password Time
					if (st.hasMoreTokens()) {
						try {
							string timeStr = st.nextToken();
							if ("*".equals(timeStr)) {
								passwordTime = NO_EXPIRATION;
							}
							else {
								passwordTime = NumericUtilities.parseHexLong(timeStr);
							}
						}
						catch (NumberFormatException e) {
							log.error(
								"Invalid password time - forced expiration: " + username);
							userMapMutated = true;
							passwordTime = 0;
						}

						// Distinguished Name
						if (st.hasMoreTokens()) {
							string dn = st.nextToken();
							if (dn.length() > 0) {
								x500Name = new X500Principal(dn);
							}

						}
					}
				}
				UserEntry entry = new UserEntry(username, x500Name, passwordHash, passwordTime);
				usersIndexByName.put(username, entry);
				if (x500Name != null) {
					x500LookupMap.put(x500Name, entry);
				}
			}
		}
		return userMapMutated;
	}

	/**
	 * Write user data to file.
	 * @throws IOException if error occurs while updating user file
	 */
	private void writeUserList()
    {
		using (BufferedWriter bw = new BufferedWriter(new FileWriter(userFile)))
{
			foreach (UserEntry entry in userMap.values()) {
				bw.write(entry.username);
				bw.write(":");
				if (entry.passwordHash != null) {
					bw.write(entry.passwordHash);
					bw.write(':');
					if (entry.passwordTime == NO_EXPIRATION) {
						bw.write('*');
					}
					else {
						bw.write(Long.toHexString(entry.passwordTime));
					}
				}
				else {
					bw.write("*:*");
				}
				if (entry.x500Name != null) {
					bw.write(":");
					bw.write(entry.x500Name.getName());
				}
				bw.newLine();
			}
		}
		lastUserListChange = userFile.lastModified();
	}

	/**
	 * Returns true if the specified user is known to server.
	 * @param username user name/SID
	 * @return true if user is known to server
	 */
	public bool isValidUser(string username) {
		lock (repositoryMgr) {
			return userMap.containsKey(username);
		}
	}

	/**
	 * Verify that the specified password corresponds to the local
	 * password set for the specified user.
	 * @param username user name/SID
	 * @param password password data
	 * @throws IOException if error occurs while updating user file
	 * @throws FailedLoginException if authentication fails
	 */
	public void authenticateUser(string username, char[] password)
    {
		if (username == null || password == null) {
			throw new FailedLoginException("Invalid authentication data");
		}
		lock (repositoryMgr) {
			clearExpiredPasswords();
			UserEntry entry = userMap.get(username);
			if (entry == null) {
				throw new FailedLoginException("Unknown user: " + username);
			}

			if (entry.passwordHash == null ||
				entry.passwordHash.length < HashUtilities.MD5_UNSALTED_HASH_LENGTH) {
				throw new FailedLoginException("User password not set, must be reset");
			}

			// Support deprecated unsalted hash
			if (entry.passwordHash.length == HashUtilities.MD5_UNSALTED_HASH_LENGTH &&
				Arrays.equals(
					HashUtilities.getHash(HashUtilities.MD5_ALGORITHM, password),
					entry.passwordHash)) {
				return;
			}

			char[] salt = new char[HashUtilities.SALT_LENGTH];
			Array.Copy(entry.passwordHash, 0, salt, 0, HashUtilities.SALT_LENGTH);

			if (entry.passwordHash.length == HashUtilities.MD5_SALTED_HASH_LENGTH) {
				if (!Arrays.equals(
					HashUtilities.getSaltedHash(HashUtilities.MD5_ALGORITHM, salt, password),
					entry.passwordHash)) {
					throw new FailedLoginException("Incorrect password");
				}
			}
			else if (entry.passwordHash.length == HashUtilities.SHA256_SALTED_HASH_LENGTH) {
				if (!Arrays.equals(
					HashUtilities.getSaltedHash(HashUtilities.SHA256_ALGORITHM, salt, password),
					entry.passwordHash)) {
					throw new FailedLoginException("Incorrect password");
				}
			}
			else {
				throw new FailedLoginException("User password not set, must be reset");
			}
		}
	}

	/**
	 * <code>UserEntry</code> record used to hold user file data
	 */
	private record UserEntry(string username, X500Principal x500Name, char[] passwordHash,
			long passwordTime) {}

	private PrintWriter getDNLog()
    {
		if (dnLogOut == null) {
			File dnLog = new File(userFile.getParentFile(), DN_LOG_FILE);
			dnLogOut = new PrintWriter(new FileOutputStream(dnLog, true), true);
		}
		return dnLogOut;
	}

	/**
	 * Log a new or unknown X500 principal to facilitate future addition to
	 * user file.
	 * @param username user name/SID which corresponds to unknown principal
	 * @param principal X500 principal data which contains user's distinguished name
	 */
	public void logUnknownDN(string username, X500Principal principal) {
		try {
			getDNLog().println(username + "; " + principal);
		}
		catch (IOException e) {
			// ignore
		}
	}

	/*
	 * Regex: matches if the entire string is alpha, digit, ".", "-", "_".
	 */
	private static readonly Pattern VALID_USERNAME_REGEX =
		Pattern.compile("[a-zA-Z0-9][a-zA-Z0-9.\\-_]*");

	/**
	 * Ensures a name only contains valid characters.
	 * 
	 * @param s name string
	 * @return boolean true if valid name, false if not valid
	 */
	public static bool isValidUserName(string s) {
		return VALID_USERNAME_REGEX.matcher(s).matches();
	}

	private static class UserMap<V> : TreeMap<string, V> where V : object {
		UserMap() : base(string.CASE_INSENSITIVE_ORDER)
    {
		}
	}

}
